package org.dextur.reputation.storage;

import java.sql.*;
import java.time.Instant;
import java.util.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.domain.investigation.InvestigationData.*;
import org.dextur.reputation.domain.investigation.InvestigationData.Record;
import org.dextur.reputation.domain.protection.*;
import org.dextur.reputation.domain.protection.ProtectionData.*;
import org.dextur.reputation.domain.policy.AdministrationData;
import org.dextur.reputation.domain.recovery.RecoveryData;
import org.dextur.reputation.domain.tier.*;

final class JdbcInvestigation extends InvestigationSession {
    final SqlStorage owner;final Connection c;final SqlVoting voting;final SqlProtection privateData;final SqlInvestigation investigation;
    JdbcInvestigation(SqlStorage owner,Connection c,Rules rules,ProtectionRules protection,TierRules tiers){super(rules,protection,tiers);this.owner=owner;this.c=c;voting=new SqlVoting(owner);privateData=new SqlProtection(owner);investigation=new SqlInvestigation(owner);}
    @Override ReputationSnapshot profile(UUID id,String scope)throws Exception{try(var q=c.prepareStatement("SELECT * FROM dr_profiles WHERE player_uuid=? AND scope_id=?")){q.setString(1,id.toString());q.setString(2,scope);try(var rows=q.executeQuery()){return rows.next()?owner.profile(rows):null;}}}
    @Override ReputationSnapshot putProfile(ReputationSnapshot p)throws Exception{try(var q=c.prepareStatement("UPDATE dr_profiles SET community_score=?,system_score=?,visible_score=?,tier=?,profile_revision=?,updated_at=? WHERE player_uuid=? AND scope_id=?")){q.setLong(1,p.communityScore());q.setLong(2,p.systemScore());q.setLong(3,p.visibleScore());q.setString(4,p.tier());q.setLong(5,p.revision());voting.time(q,6,p.updatedAt());q.setString(7,p.playerId().toString());q.setString(8,p.scopeId());if(q.executeUpdate()!=1)throw new SQLException("Missing moderation profile");}return owner.reconcileTier(c,p);}
    @Override TierState tier(UUID id,String scope)throws Exception{return new SqlTiers(owner).get(c,id,scope);}
    @Override void putTier(TierState tier)throws Exception{new SqlTiers(owner).put(c,tier);}
    @Override VoteStatistics statistics(UUID id,String scope)throws Exception{long positive=0,negative=0,unique=0,total=0;try(var q=c.prepareStatement("SELECT SUM(CASE WHEN vote_type='POSITIVE' THEN 1 ELSE 0 END),SUM(CASE WHEN vote_type='NEGATIVE' THEN 1 ELSE 0 END) FROM dr_active_votes WHERE scope_id=? AND target_uuid=?")){q.setString(1,scope);q.setString(2,id.toString());try(var rows=q.executeQuery()){rows.next();positive=rows.getLong(1);negative=rows.getLong(2);}}try(var q=c.prepareStatement("SELECT COUNT(DISTINCT voter_uuid),COUNT(*) FROM dr_votes WHERE scope_id=? AND target_uuid=?")){q.setString(1,scope);q.setString(2,id.toString());try(var rows=q.executeQuery()){rows.next();unique=rows.getLong(1);total=rows.getLong(2);}}return new VoteStatistics(positive,negative,unique,total);}
    @Override Trust trust(UUID id,String scope)throws Exception{return privateData.get(c,"dr_trust",id+"/"+scope,Trust.class);}
    @Override Score score(UUID id,String scope)throws Exception{return privateData.get(c,"dr_precision",id+"/"+scope,Score.class);}
    @Override void putTrust(Trust trust)throws Exception{privateData.put(c,"dr_trust",trust,false);}
    @Override AdministrationData.State administration(UUID id,String scope)throws Exception{return new SqlAdministration(owner).get(c,id,scope);}
    @Override RecoveryData.State recovery(UUID id,String scope)throws Exception{return new SqlRecovery(owner).get(c,id,scope);}
    @Override VoteEntry vote(UUID id)throws Exception{return voting.operation(c,id);}
    @Override Assessment assessment(UUID id)throws Exception{return privateData.get(c,"dr_vote_assessments",id.toString(),Assessment.class);}
    @Override View context(VoteEntry v,Instant now)throws Exception{return privateData.context(c,v.voterId(),v.targetId(),v.scope(),protection,now);}
    @Override VoteEntry latest(VoteEntry v)throws Exception{try(var q=c.prepareStatement("SELECT * FROM dr_votes WHERE scope_id=? AND voter_uuid=? AND target_uuid=? ORDER BY sequence_no DESC LIMIT 1")){q.setString(1,v.scope());q.setString(2,v.voterId().toString());q.setString(3,v.targetId().toString());try(var rows=q.executeQuery()){return rows.next()?voting.read(rows):null;}}}
    @Override VoteEntry active(VoteEntry v)throws Exception{try(var q=c.prepareStatement("SELECT v.* FROM dr_active_votes a JOIN dr_votes v ON v.operation_id=a.operation_id WHERE a.scope_id=? AND a.voter_uuid=? AND a.target_uuid=?")){q.setString(1,v.scope());q.setString(2,v.voterId().toString());q.setString(3,v.targetId().toString());try(var rows=q.executeQuery()){return rows.next()?voting.read(rows):null;}}}
    @Override void change(Change change)throws Exception{privateData.persist(c,change);owner.reconcileTier(c,change.profile());}
    private static final String STATUS="CASE WHEN m.status='INVALIDATED' THEN 'INVALIDATED' WHEN a.status IS NOT NULL THEN a.status WHEN v.action='REVOKE' THEN 'REVOKED' WHEN active.operation_id IS NOT NULL THEN 'ACCEPTED' ELSE 'SUPERSEDED' END";
    private static final String FROM=" FROM dr_votes v LEFT JOIN dr_vote_assessments a ON a.record_key=v.operation_id LEFT JOIN dr_active_votes active ON active.operation_id=v.operation_id LEFT JOIN dr_investigation m ON m.kind='MODERATION' AND m.record_id=v.operation_id";
    private static String from(Filter f){return f.status().isEmpty()&&f.severity().isEmpty()&&f.source().isEmpty()?" FROM dr_votes v":FROM;}
    @Override Map<String,String> voteSummary(UUID id,String scope)throws Exception {
        var counts=new TreeMap<String,Long>();for(String status:List.of("accepted","suspicious","invalidated","pending"))counts.put("count_"+status,0L);counts.put("positive",0L);counts.put("negative",0L);
        // Partition the exact CASE status rules. Superseded legacy history needs no payload join.
        String assessed="SELECT CASE WHEN m.status='INVALIDATED' THEN 'INVALIDATED' ELSE a.status END AS vote_status,v.vote_type,COUNT(*) FROM dr_vote_assessments a JOIN dr_votes v ON v.operation_id=a.record_key LEFT JOIN dr_investigation m ON m.kind='MODERATION' AND m.record_id=v.operation_id WHERE a.scope_id=? AND a.target_uuid=? GROUP BY vote_status,v.vote_type";
        String legacyActive="SELECT CASE WHEN m.status='INVALIDATED' THEN 'INVALIDATED' ELSE 'ACCEPTED' END AS vote_status,active.vote_type,COUNT(*) FROM dr_active_votes active LEFT JOIN dr_vote_assessments a ON a.record_key=active.operation_id LEFT JOIN dr_investigation m ON m.kind='MODERATION' AND m.record_id=active.operation_id WHERE active.scope_id=? AND active.target_uuid=? AND a.record_key IS NULL GROUP BY vote_status,active.vote_type";
        for(String sql:List.of(assessed,legacyActive))try(var q=c.prepareStatement(sql)){q.setString(1,scope);q.setString(2,id.toString());try(var rows=q.executeQuery()){addCounts(rows,counts);}}
        String inactive="SELECT 'INVALIDATED',v.vote_type,COUNT(*) FROM dr_investigation m JOIN dr_votes v ON v.operation_id=m.record_id LEFT JOIN dr_vote_assessments a ON a.record_key=v.operation_id LEFT JOIN dr_active_votes active ON active.operation_id=v.operation_id WHERE m.scope_id=? AND m.kind='MODERATION' AND m.status='INVALIDATED' AND v.scope_id=? AND v.target_uuid=? AND a.record_key IS NULL AND active.operation_id IS NULL GROUP BY v.vote_type";
        try(var q=c.prepareStatement(inactive)){q.setString(1,scope);q.setString(2,scope);q.setString(3,id.toString());try(var rows=q.executeQuery()){addCounts(rows,counts);}}
        var statistics=statistics(id,scope);counts.put("unique_voters",statistics.uniqueVoters());counts.put("active",statistics.positive()+statistics.negative());var values=new TreeMap<String,String>();counts.forEach((key,value)->values.put(key,Long.toString(value)));return values;
    }
    private static void addCounts(ResultSet rows,Map<String,Long> counts)throws SQLException {
        while(rows.next()){String status=rows.getString(1);long n=rows.getLong(3);String key="count_"+status.toLowerCase(Locale.ROOT);if(counts.containsKey(key))counts.merge(key,n,Long::sum);if(status.equals("ACCEPTED")||status.equals("SUSPICIOUS"))counts.merge(rows.getString(2).equals("POSITIVE")?"positive":"negative",n,Long::sum);}
    }
    private record Selection(String where,List<Object> arguments){}
    private Selection selection(String scope,Filter f)throws Exception{
        var sql=new StringBuilder(" WHERE v.scope_id=?");var args=new ArrayList<Object>();args.add(scope);
        if(f.voter()!=null){sql.append(" AND v.voter_uuid=?");args.add(f.voter().toString());}if(f.target()!=null){sql.append(" AND v.target_uuid=?");args.add(f.target().toString());}if(f.type()!=null){sql.append(" AND v.vote_type=?");args.add(f.type().name());}
        if(f.status().equals("PENDING")){sql.append(" AND a.status=?");args.add("PENDING");}else if(!f.status().isEmpty()){sql.append(" AND ("+STATUS+")=?");args.add(f.status());}if(f.before()!=null){sql.append(" AND v.created_at<=?");args.add(f.before());}if(f.after()!=null){sql.append(" AND v.created_at>=?");args.add(f.after());}
        if(!f.severity().isEmpty()){sql.append(" AND a.payload LIKE ?");args.add("%\"severity\":\""+f.severity()+"\"%");}if(!f.source().isEmpty()){sql.append(" AND a.payload LIKE ?");args.add("%\""+f.source()+"\"%");}
        if(!f.search().isEmpty()){String comment=owner.type()==org.dextur.reputation.application.StorageType.MYSQL?"CAST(v.comment_text AS BINARY)":"v.comment_text";sql.append(" AND (INSTR("+comment+",?)>0 OR INSTR("+(owner.type()==org.dextur.reputation.application.StorageType.MYSQL?"CAST(v.reason_id AS BINARY)":"v.reason_id")+",?)>0 OR INSTR(v.operation_id,?)>0)");args.add(f.search());args.add(f.search());args.add(f.search());}
        if(f.flag()!=null){var flag=record(Kind.FLAG,f.flag());sql.append(" AND v.operation_id=?");args.add(flag==null?"unknown":flag.vote().toString());}
        return new Selection(sql.toString(),args);
    }
    private int bind(PreparedStatement q,List<Object> values)throws Exception{int i=1;for(var value:values){if(value instanceof Instant instant)voting.time(q,i++,instant);else q.setString(i++,value.toString());}return i;}
    @Override List<VoteEntry> select(String scope,Filter filter,int limit,long offset)throws Exception{var f=selection(scope,filter);var result=new ArrayList<VoteEntry>();try(var q=c.prepareStatement("SELECT v.* FROM (SELECT v.operation_id,v.sequence_no"+from(filter)+f.where()+" ORDER BY v.sequence_no DESC LIMIT ? OFFSET ?) page JOIN dr_votes v ON v.operation_id=page.operation_id ORDER BY page.sequence_no DESC")){int i=bind(q,f.arguments());q.setInt(i++,limit);q.setLong(i,offset);try(var rows=q.executeQuery()){while(rows.next())result.add(voting.read(rows));}}return result;}
    @Override long count(String scope,Filter filter)throws Exception{var f=selection(scope,filter);try(var q=c.prepareStatement("SELECT COUNT(*)"+from(filter)+f.where())){bind(q,f.arguments());try(var rows=q.executeQuery()){rows.next();return rows.getLong(1);}}}
    @Override List<Audit> protectionAudit(String scope,UUID target,int limit,long offset)throws Exception{var result=new ArrayList<Audit>();try(var q=c.prepareStatement("SELECT payload FROM dr_protection_audit WHERE scope_id=?"+(target==null?"":" AND target_uuid=?")+" ORDER BY sequence_no LIMIT ? OFFSET ?")){int i=1;q.setString(i++,scope);if(target!=null)q.setString(i++,target.toString());q.setInt(i++,limit);q.setLong(i,offset);try(var rows=q.executeQuery()){while(rows.next())result.add(ProtectionCodec.decode(rows.getString(1),Audit.class));}}return result;}
    @Override Record record(Kind kind,UUID id)throws Exception{return investigation.get(c,kind,id);}
    @Override List<Record> records(Kind kind,String scope,UUID target,UUID vote,int limit,long offset)throws Exception{return investigation.list(c,kind,scope,target,vote,limit,offset);}
    private Selection recordSelection(Kind kind,String scope,UUID target,Filter f){var sql=new StringBuilder(" WHERE kind=? AND scope_id=?");var args=new ArrayList<Object>();args.add(kind.name());args.add(scope);if(target!=null){sql.append(" AND target_uuid=?");args.add(target.toString());}if(!f.status().isEmpty()){sql.append(" AND status=?");args.add(f.status());}if(!f.source().isEmpty()){sql.append(" AND INSTR(payload,?)>0");args.add("\"source\":\""+f.source()+"\"");}if(!f.severity().isEmpty()){sql.append(" AND INSTR(payload,?)>0");args.add("\"severity\":\""+f.severity()+"\"");}if(!f.search().isEmpty()){sql.append(" AND INSTR("+(owner.type()==org.dextur.reputation.application.StorageType.MYSQL?"CAST(payload AS BINARY)":"payload")+",?)>0");args.add(f.search());}if(f.before()!=null){sql.append(" AND created_at<=?");args.add(f.before());}if(f.after()!=null){sql.append(" AND created_at>=?");args.add(f.after());}return new Selection(sql.toString(),args);}
    @Override List<Record> filteredRecords(Kind kind,String scope,UUID target,Filter filter,int limit,long offset)throws Exception{var f=recordSelection(kind,scope,target,filter);var result=new ArrayList<Record>();try(var q=c.prepareStatement("SELECT * FROM dr_investigation"+f.where()+" ORDER BY created_at DESC,record_id LIMIT ? OFFSET ?")){int i=bind(q,f.arguments());q.setInt(i++,limit);q.setLong(i,offset);try(var rows=q.executeQuery()){while(rows.next())result.add(investigation.read(rows));}}return result;}
    @Override long countRecords(Kind kind,String scope,UUID target,Filter filter)throws Exception{var f=recordSelection(kind,scope,target,filter);try(var q=c.prepareStatement("SELECT COUNT(*) FROM dr_investigation"+f.where())){bind(q,f.arguments());try(var rows=q.executeQuery()){rows.next();return rows.getLong(1);}}}
    @Override Report trustHistory(UUID player,String scope,int page,int size)throws Exception{String union="SELECT 'PRIVATE' AS origin,record_key AS identity_key,updated_at AS event_time,payload FROM dr_protection_audit WHERE scope_id=? AND actor_uuid=? AND INSTR(payload,'\"kind\":\"ANALYSIS\"')=0 UNION ALL SELECT 'ADMIN' AS origin,record_id AS identity_key,created_at AS event_time,payload FROM dr_investigation WHERE scope_id=? AND kind='AUDIT' AND target_uuid=? AND (INSTR(payload,'\"action\":\"RECALCULATE_TRUST\"')>0 OR INSTR(payload,'\"action\":\"RECALCULATE_ALL\"')>0)";long total;try(var q=c.prepareStatement("SELECT COUNT(*) FROM ("+union+") AS history")){q.setString(1,scope);q.setString(2,player.toString());q.setString(3,scope);q.setString(4,player.toString());try(var rows=q.executeQuery()){rows.next();total=rows.getLong(1);}}var result=new ArrayList<Row>();try(var q=c.prepareStatement("SELECT * FROM ("+union+") AS history ORDER BY event_time DESC,identity_key LIMIT ? OFFSET ?")){q.setString(1,scope);q.setString(2,player.toString());q.setString(3,scope);q.setString(4,player.toString());q.setInt(5,size);q.setLong(6,((long)page-1)*size);try(var rows=q.executeQuery()){while(rows.next())result.add(rows.getString("origin").equals("PRIVATE")?InvestigationReports.trustAudit(ProtectionCodec.decode(rows.getString("payload"),Audit.class)):InvestigationReports.record(ProtectionCodec.decode(rows.getString("payload"),Record.class)));}}return new Report(Map.of("uuid",player.toString(),"page",Integer.toString(page)),result,total,InvestigationEngine.hash(result));}
    @Override void put(Record r)throws Exception{investigation.put(c,r);}
    @Override long recordCount()throws Exception{try(var q=c.createStatement();var rows=q.executeQuery("SELECT COUNT(*) FROM dr_investigation")){rows.next();return rows.getLong(1);}}
}
